function createShowMoreBtn(){let n=document.createElement("a");return n.innerText="+ نمایش بیشتر",n.setAttribute("data-isactive","true"),n.setAttribute("onclick","toggleLiVisibility(this)"),n.classList.add("showMoreBtn"),n}function toggleLiVisibility(n){if(n.dataset.isactive=="true"){for(let t=n.parentElement.childElementCount-1;t>=VisibleLiCount;t--)n.parentElement.children[t].style.display="block";n.innerText="- نمایش کمتر";n.dataset.isactive=!1}else{for(let t=n.parentElement.childElementCount-1;t>=VisibleLiCount;t--)n.parentElement.children[t].style.display="none";n.innerText="+ نمایش بیشتر";n.dataset.isactive=!0}n.style.display="block"}function openAdvancedFilter(){document.querySelector("body").style.overflowY="hidden";document.querySelector(".sidebar-desktop").style.transform="translateY(0%)"}function closeAdvancedFilter(){document.querySelector("body").style.overflowY="auto";document.querySelector(".sidebar-desktop").style.transform="translateY(100%)"}function deleteFilter(n){n.parentElement.remove()}let VisibleLiCount=7,allSubmenuUls=document.querySelectorAll(".submenu"),i=0;allSubmenuUls.forEach(n=>{if(n.childElementCount>VisibleLiCount){for(let t=n.childElementCount-1;t>=VisibleLiCount;t--)n.children[t].style.display="none";n.appendChild(createShowMoreBtn())}});$(function(){$(".list-group-item").on("click",function(){$(".glyphicon",this).toggleClass("glyphicon-chevron-right").toggleClass("glyphicon-chevron-down")})});document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".sidebar .has-submenu").forEach(function(n){n.addEventListener("click",function(t){let r=n.querySelector(".nav-link"),i=r.nextElementSibling,u=r.querySelector("img");if(i&&t.target.nodeName!="A"){t.stopPropagation();t.preventDefault();u.style.transform=i.classList.contains("show")?"rotate(0deg)":"rotate(-90deg)";let n=new bootstrap.Collapse(i,!1);i.classList.contains("show")?n.hide():n.show()}})})});